            new Quote { Id = "https://ar.wikiquote.org/wiki/أمل_دنقل", Text = "وكــأن الــذُّل فــي الشَّعــب ضريـبــة وإبتســام الصَّبــر قــد صــار ذنوبـــه", Author = "أمل دنقل" },
