            new Quote { Id = "https://ar.wikiquote.org/wiki/أمل_دنقل", Text = "معلق أنا على مشانق الصباح و جبهتى – بالموت – محنية لأننى لم أحنها .. حيه", Author = "أمل دنقل" },
