            new Quote { Id = "https://ar.wikiquote.org/wiki/أمل_دنقل", Text = "آه من في غد سوف يرفع هامته؟ غير من طأطأوا حين أزَّ الرصاص؟ -ومن سوف يخطب - في ساحة الشهداء سوى الجبناء؟ ومن سوف يغوى الأرامل؟ إلا الذي سيؤول إليه خراج المدينة!!؟", Author = "أمل دنقل" },
